<?php namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Role; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash;
class UserController extends Controller {public function index(Request $r){$q=User::with('roles');if($r->filled('q'))$q->where(fn($x)=>$x->where('name','like','%'.$r->q.'%')->orWhere('email','like','%'.$r->q.'%'));return view('admin.users.index',['items'=>$q->latest()->paginate(20)->withQueryString(),'roles'=>Role::orderBy('name')->get()]);}public function store(Request $r){$d=$r->validate(['name'=>'required|max:150','email'=>'required|email|max:190|unique:users,email','phone'=>'nullable|max:30|unique:users,phone','password'=>'required|min:8','role_id'=>'required|exists:roles,id']);$u=User::create([...$d,'password'=>Hash::make($d['password']),'status'=>'active']);$u->roles()->sync([$d['role_id']]);return back()->with('success','User created.');}public function update(Request $r,User $user){$d=$r->validate(['name'=>'required|max:150','status'=>'required|in:active,inactive,suspended','role_id'=>'required|exists:roles,id']);$user->update(['name'=>$d['name'],'status'=>$d['status']]);$user->roles()->sync([$d['role_id']]);return back()->with('success','User updated.');}}
